WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pf_m_extreme'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '利润与最值综合', 'kp-pf-m-extreme', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "利润与最值综合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "降价促销模型。求利润最大化。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "总利润 y = (原单件利润 - 降价幅度x) × (原销量 + 销量增幅 × x)"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、秒杀法则（中点法则）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是一个开口向下的二次函数。令两个括号分别等于 0，求出两个 x 的截距。最大利润永远在【两个截距的中间点】处取得！"}]}]}$$ AS jsonb), NULL, '利润与最值综合的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "利润与最值综合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_m_extreme", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
